import { concept, exercise, predict, type Concept } from './concepts.ts';
export const advancedConcepts:Concept[]=[
 concept({id:'function-machine',lesson:7,title:'Functions: reusable behavior, parameters & arguments',minutes:12,visual:'function',what:'A function is a callable object containing reusable instructions. Defining it creates the function; calling it runs its body.',why:'A single definition can handle many inputs without copying the same business logic.',real:'A calculator, price rule, and form validator can call reusable helpers from several interface events.',analogy:'A vending machine receives inputs, performs steps, and produces an output. It does not dispense anything merely because the machine exists.',how:'function greet() { console.log("Hello!"); } declares a named function. function introduces the declaration, greet is its name, () contains parameters, and braces enclose its body. greet(); calls it with no arguments. In function add(a,b) { return a+b; }, a and b are parameters (local input names). In add(10,20), 10 and 20 are arguments (actual supplied values). Each call gets its own local bindings; calls share outer bindings only when the code refers to them.',confusion:'Writing greet without () refers to the function value; it does not run it. Parameter names do not force the caller to use matching variable names.',takeaway:'Define once. Call with arguments. Receive a result.',examples:[{title:'Define, then call',code:'function greet() {\n  console.log("Hello!");\n}\ngreet();\ngreet();',explanation:'The declaration creates the function. Each call executes the log once.'},{title:'Arguments become parameters',code:'function add(a, b) {\n  return a + b;\n}\nconst firstPrice = 10;\nconsole.log(add(firstPrice, 20));\nconsole.log(add(3, 4));',explanation:'The first argument is mapped to a, the second to b. The caller’s variable name is irrelevant.'}],predictions:[predict('v2-function-p1','function greet() { console.log("Hi"); }\nconsole.log(typeof greet);\ngreet();',['Hi then function','function then Hi','undefined'],1,'typeof inspects the function value without calling it; the explicit call prints Hi.',['function','Hi']),predict('v2-function-p2','function add(a, b) { return a + b; }\nconsole.log(add(10, 20), add(1, 2));',['30 3','10 1','undefined undefined'],0,'Each call receives its own parameter values and returns their sum.',['30 3'])],debug:exercise('Actually call the helper.','function total() { return 50; }\nconsole.log(typeof total);','function total() { return 50; }\nconsole.log(total());','Use parentheses to invoke a function.'),activity:exercise('Create a reusable temperature converter from Celsius to Fahrenheit.','function toFahrenheit(celsius) {\n // Return the converted value\n}\nconsole.log(toFahrenheit(0), toFahrenheit(100));','function toFahrenheit(celsius) {\n return celsius * 9 / 5 + 32;\n}\nconsole.log(toFahrenheit(0), toFahrenheit(100));','Multiply by 9/5 and add 32.'),demo:'Enter two arguments in the Function Machine and step through parameter binding, calculation, and return.',transition:'A function can print something without returning a useful result.'}),
 concept({id:'function-returns',lesson:7,title:'Return values, printing & guard clauses',minutes:10,visual:'returns',what:'A return hands a value to the caller and stops that call. Logging displays a message but does not choose the function’s return value.',why:'Returned values can be reused in calculations, tests, or another function.',real:'A BMI helper returns a number in kg/m² so an interface can display it. This project demonstrates arithmetic, not medical interpretation.',analogy:'A chef may announce that lunch is ready, but you still need the actual plate. An announcement is not the returned product.',how:'A function without an executed value-return returns undefined. return; also returns undefined. A guard clause handles invalid input with an early return. Put the return expression on the same line: a newline after return can trigger semicolon insertion, returning undefined instead. Object-returning arrow functions need parentheses around an object literal: () => ({ok:true}).',confusion:'const result = console.log(5) stores undefined, because logging itself does not return 5.',takeaway:'Print to observe. Return to reuse.',examples:[{title:'Print versus return',code:'function printDouble(n) { console.log(n * 2); }\nfunction double(n) { return n * 2; }\nconsole.log(printDouble(4));\nconsole.log(double(4) + 1);',explanation:'The first call prints 8 then yields undefined; double returns 8, allowing addition to produce 9.'},{title:'Guard invalid units',code:'function bmi(weightKg, heightM) {\n if (!Number.isFinite(weightKg) || !Number.isFinite(heightM) || weightKg <= 0 || heightM <= 0) return null;\n return weightKg / (heightM ** 2);\n}\nconsole.log(bmi(72, 1.8).toFixed(2));\nconsole.log(bmi(72, 0));',explanation:'The function explicitly expects kilograms and meters. Invalid input exits before division.'}],predictions:[predict('v2-freturn-p1','function message() { console.log("Ready"); }\nconst result = message();\nconsole.log(result);',['Ready then undefined','Ready then Ready','undefined'],0,'Logging does not supply a return value. The function reaches its end.',['Ready','undefined']),predict('v2-freturn-p2','function make() {\n return\n { ok: true };\n}\nconsole.log(make());',['{"ok": true}','undefined','SyntaxError'],1,'Automatic semicolon insertion ends return before the following line.',['undefined'])],debug:exercise('Return the object on the same line.','function make() {\n return\n { ok: true };\n}\nconsole.log(make());','function make() {\n return { ok: true };\n}\nconsole.log(make());','A newline immediately after return changes the result.'),activity:exercise('Write an input validator that returns a boolean, without printing inside it.','function validScore(value) {\n // Accept finite scores from 0 through 100\n}\nconsole.log(validScore(90), validScore(NaN));','function validScore(value) {\n return Number.isFinite(value) && value >= 0 && value <= 100;\n}\nconsole.log(validScore(90), validScore(NaN));','Return the combined condition.'),demo:'Use the Return Visualizer to compare log-only, ordinary return, and early return paths.',transition:'The same reusable behavior can be written in several function forms.'}),
 concept({id:'function-forms',lesson:7,title:'Declarations, expressions, arrows & callbacks',minutes:12,visual:'function-forms',what:'A declaration names a function directly. An expression produces a function value. An arrow is a compact function-expression syntax.',why:'Functions can be stored, passed as arguments, and called by other functions.',real:'An array transformation calls a callback for every item; a button calls a handler when clicked.',analogy:'A named recipe can be kept in a cookbook, assigned to a card, or handed to someone else to carry out.',how:'function add(a,b) { return a+b; } is a declaration. const add = function(a,b) { return a+b; }; stores an expression. const add = (a,b) => a+b; uses an implicit return; braces require an explicit return. A callback is a function passed to another function, not a different JavaScript type. Function declarations in these function-body examples can be called before their written position. A const expression is in its TDZ until initialized; a var expression starts undefined, and an early call throws TypeError. Arrows have no own arguments object and cannot be used as constructors with new. See the optional this section before using arrows as methods.',confusion:'An arrow with { n * 2; } has a block body and returns undefined unless you write return.',takeaway:'Choose clear syntax; remember whether the body implicitly returns.',examples:[{title:'Compare three forms',code:'function declaration(a, b) { return a + b; }\nconst expression = function (a, b) { return a + b; };\nconst arrow = (a, b) => a + b;\nconsole.log(declaration(2, 3), expression(2, 3), arrow(2, 3));',explanation:'All three return 5, but they differ in setup and advanced this behavior.'},{title:'A first callback',code:'function applyTwice(value, transform) {\n return transform(transform(value));\n}\nconst addOne = n => n + 1;\nconsole.log(applyTwice(3, addOne));\nconsole.log([1, 2, 3].map(n => n * 2));',explanation:'The function value addOne is passed, not called at the argument site. map is explored in the next chapter.'}],predictions:[predict('v2-forms-p1','const double = n => { n * 2; };\nconsole.log(double(4));',['8','undefined','SyntaxError'],1,'A block-bodied arrow requires an explicit return.',['undefined']),predict('v2-forms-p2','console.log(add(2, 3));\nfunction add(a, b) { return a + b; }',['5','undefined','ReferenceError'],0,'A function-body declaration is initialized with its function value before these statements run.',['5'])],debug:exercise('Make this arrow return its computed value.','const double = n => { n * 2; };\nconsole.log(double(4));','const double = n => { return n * 2; };\nconsole.log(double(4));','Add return or remove the braces for an expression body.'),activity:exercise('Accept a transformation callback and apply it to a number.','function transform(value, action) {\n // Use the callback and return its result\n}\nconsole.log(transform(5, n => n * n));','function transform(value, action) {\n return action(value);\n}\nconsole.log(transform(5, n => n * n));','A function parameter can hold another function.'),demo:'Change a function’s form in the comparison, then inspect its code and result. Toggle arrow braces to see return behavior.',transition:'Default and rest parameters make inputs more flexible.'}),
 concept({id:'function-inputs',lesson:7,title:'Default parameters & rest parameters',minutes:10,visual:'parameters',what:'A default parameter supplies a fallback when an argument is missing or undefined. A rest parameter collects remaining arguments into an array.',why:'A helper can support optional inputs or an unknown number of inputs without manual argument handling.',real:'A greeting defaults to Guest; a bill-total function accepts any number of prices.',analogy:'A café uses regular milk if you do not specify one, and a basket collects however many snacks you order.',how:'function greet(name="Guest") uses the default only for undefined, not null, 0, or "". A rest parameter such as ...prices must be last and is a real array. It collects arguments; spread at a call such as sum(...numbers) does the opposite by expanding an iterable into arguments. Defaults are evaluated when the call happens. Rest replaces the need for an arguments object in these examples.',confusion:'... can collect in a parameter list or expand at a call site. Its role depends on position.',takeaway:'Default fills one missing input; rest collects many inputs; spread expands a list.',examples:[{title:'When defaults apply',code:'function greet(name = "Guest") { return "Hello, " + name; }\nconsole.log(greet());\nconsole.log(greet(undefined));\nconsole.log(greet(null));\nconsole.log(greet(""));',explanation:'Only missing and undefined arguments use Guest.'},{title:'Collect and expand',code:'function sum(...numbers) {\n let total = 0;\n for (const number of numbers) total += number;\n return total;\n}\nconsole.log(sum(10, 20, 30));\nconst prices = [5, 10];\nconsole.log(sum(...prices));',explanation:'Rest creates an array inside sum. Spread sends the array’s elements as separate arguments.'}],predictions:[predict('v2-inputs-p1','function value(x = 10) { return x; }\nconsole.log(value(undefined), value(null), value(0));',['10 10 10','10 null 0','undefined null 0'],1,'Defaults apply to undefined, not other falsy values.',['10 null 0']),predict('v2-inputs-p2','function count(first, ...others) { return others.length; }\nconsole.log(count("a", "b", "c"));',['3','2','1'],1,'The first argument binds to first; the remaining two are collected.',['2'])],debug:exercise('Put the rest parameter last.','function total(...values, tax) { return values.length; }\nconsole.log(total(1, 2));','function total(tax, ...values) { return values.length; }\nconsole.log(total(0.1, 1, 2));','No parameter can follow a rest parameter.'),activity:exercise('Write a reusable discount function with a default percentage of 10.','function discountedPrice(total, percent = 10) {\n // Return the reduced total\n}\nconsole.log(discountedPrice(100), discountedPrice(100, 20));','function discountedPrice(total, percent = 10) {\n return total * (1 - percent / 100);\n}\nconsole.log(discountedPrice(100), discountedPrice(100, 20));','A default is used when the second argument is omitted.'),demo:'Remove an argument, pass undefined, null, or 0, and compare the parameter mapping. Add more arguments to the rest basket.',transition:'Optional deeper work: understand what this depends on before choosing arrows for methods.'}),
 concept({id:'function-this',lesson:7,title:'Optional deeper dive: regular this & lexical this',minutes:14,advanced:true,visual:'this',what:'For an ordinary function, this depends on how it is called. An arrow has no own this and uses the surrounding lexical this.',why:'Reusing a method or passing it as a callback changes its call site and may change its receiver.',real:'A profile method called as user.label() sees user, but a detached method may not.',analogy:'An ordinary method receives a name badge from the caller. An arrow keeps the badge from the room where it was created.',how:'These examples explicitly use strict mode. obj.method() supplies obj as this; a detached strict regular call has undefined as this. call can explicitly supply a receiver. An arrow created inside a method captures that method call’s this; call does not replace an arrow’s lexical this. An arrow at the top of an object literal does not automatically capture that object: object literals do not create a this binding. Top-level this differs between classic scripts, modules, and wrappers; do not infer it from this lab. Closure scope and this are separate ideas.',confusion:'this is not always the object in which a function was written. A detached regular method loses that receiver; an arrow does not invent an object receiver.',takeaway:'Regular function: inspect the call. Arrow: inspect the surrounding this.',examples:[{title:'Call site supplies the receiver',code:'"use strict";\nfunction readName() { return this.name; }\nconst a = { name: "Asha", readName };\nconst b = { name: "Dev", readName };\nconsole.log(a.readName(), b.readName());\nconsole.log(readName.call({ name: "Mira" }));',explanation:'One function receives three different this values through three different calls.'},{title:'An arrow remembers its surrounding receiver',code:'"use strict";\nconst user = {\n name: "Asha",\n makeReader() { return () => this.name; }\n};\nconst reader = user.makeReader();\nconsole.log(reader.call({ name: "Dev" }));',explanation:'The arrow captured this from user.makeReader(). call cannot override it.'}],predictions:[predict('v2-this-p1','"use strict";\nconst user = { name: "Asha", read() { return this.name; } };\nconst detached = user.read;\nconsole.log(detached());',['Asha','undefined','TypeError'],2,'The detached strict regular call has this === undefined; reading its name throws.',[],'TypeError'),predict('v2-this-p2','"use strict";\nconst user = { name: "Asha", make() { return () => this.name; } };\nconst read = user.make();\nconsole.log(read.call({ name: "Dev" }));',['Asha','Dev','ReferenceError'],0,'The arrow retains the surrounding method call’s this.',['Asha'])],debug:exercise('Call the method with its intended receiver.','"use strict";\nconst user = { name: "Asha", read() { return this.name; } };\nconst read = user.read;\nconsole.log(read());','"use strict";\nconst user = { name: "Asha", read() { return this.name; } };\nconst read = user.read;\nconsole.log(read.call(user));','Supply the receiver with call, or call user.read().'),activity:exercise('Return a callback that remembers the receiver of a regular method.','"use strict";\nconst counter = { value: 5, makeReader() { /* return an arrow */ } };\nconsole.log(counter.makeReader()());','"use strict";\nconst counter = { value: 5, makeReader() { return () => this.value; } };\nconsole.log(counter.makeReader()());','Create the arrow inside the method call’s environment.'),demo:'Choose regular method, detached strict call, or captured arrow in the receiver visualizer.',transition:'Callbacks become particularly useful when working with arrays.'}),
 concept({id:'array-basics',lesson:8,title:'Arrays: indexed collections & memory boxes',minutes:10,visual:'array',what:'An array is an object designed to hold an ordered collection, with zero-based indexed elements and a length property.',why:'Lists such as products, marks, and tasks should not require a separate variable for every item.',real:'A shopping cart stores a collection of product records; a marks analyzer stores numeric results.',analogy:'A numbered row of lockers starts at locker 0. length tells you the range of positions, not necessarily how many positions are filled in a sparse array.',how:'Create arrays with []. Read items[0], update items[1] = value, and inspect items.length. Arrays can contain mixed types, including other arrays or objects, but consistent data is easier to process. A missing index reads undefined. const allows element mutation while preventing reassignment of the array binding. Assigning an array to another variable shares its object identity. Avoid using delete for ordinary list removal because it leaves a hole without shrinking length; splice removes and shifts elements.',confusion:'The last ordinary index is length - 1, not length. typeof an array is object, so use Array.isArray.',takeaway:'Array = ordered values, starting at index 0.',examples:[{title:'Create, read, and update',code:'const fruits = ["Apple", "Mango", "Banana"];\nconsole.log(fruits[0], fruits.length);\nfruits[1] = "Orange";\nconsole.log(fruits);\nconsole.log(fruits[3]);',explanation:'There are three elements at indices 0, 1, and 2. Index 3 is missing.'},{title:'Arrays can contain records',code:'const students = [{ name: "Asha", marks: 82 }, { name: "Dev", marks: 68 }];\nconsole.log(students[0].name, students[1].marks);\nconsole.log(typeof students, Array.isArray(students));',explanation:'Indexing selects a record, then dot notation reads a property.'}],predictions:[predict('v2-array-p1','const values = [10, 20, 30];\nconsole.log(values[0], values[values.length]);',['10 30','10 undefined','20 30'],1,'Indices start at 0; length is one past the last ordinary index.',['10 undefined']),predict('v2-array-p2','const items = [1, 2];\nconst other = items;\nother[0] = 9;\nconsole.log(items[0], items === other);',['1 false','9 true','TypeError'],1,'Arrays are objects; assignment shares the same reference.',['9 true'])],debug:exercise('Read the last element correctly.','const marks = [75, 82, 91];\nconsole.log(marks[marks.length]);','const marks = [75, 82, 91];\nconsole.log(marks[marks.length - 1]);','The last index is one less than length.'),activity:exercise('Update one student mark and calculate a simple average with a loop.','const marks = [60, 70, 80];\n// Update index 1 to 90, then print the average\n','const marks = [60, 70, 80];\nmarks[1] = 90;\nlet sum = 0;\nfor (const mark of marks) sum += mark;\nconsole.log(sum / marks.length);','Modify the element, sum all values, then divide by length.'),demo:'Edit an indexed memory box and observe index, value, and length. Include an out-of-range read.',transition:'Array methods add, remove, copy, and reorder elements.'}),
 concept({id:'array-methods',lesson:8,title:'push, pop, shift, unshift, splice, slice & reverse',minutes:16,visual:'array-methods',what:'Array methods are functions on array objects. Some mutate the original; others return a new array.',why:'A task list needs to add, remove, and copy items without confusing the returned result with the list itself.',real:'push adds a task, splice removes an item by index, and slice copies a visible portion.',analogy:'You can change the original row of lockers, or take a photograph of part of the row. A photograph is a new container.',how:'push(...items) appends and returns the new length. pop() removes and returns the last element; shift() does the same at the front. unshift(...items) prepends and returns length. On an empty array, pop/shift return undefined. splice(start,deleteCount,...items) mutates and returns an array of removed elements. slice(start,end) returns a shallow copy with an exclusive end and does not mutate. Negative indices in these selection methods count from the end. reverse() mutates and returns the original array reference. sort also mutates, covered next. None of these shallow selection/copy operations independently clones nested objects.',confusion:'items = items.push("New") replaces the array variable with a number. push returns length, not the array.',takeaway:'Always ask two questions: what changed, and what was returned?',examples:[{title:'Different return types',code:'const tasks = ["Read", "Code"];\nconsole.log(tasks.push("Test"));\nconsole.log(tasks.pop());\nconsole.log(tasks.unshift("Plan"));\nconsole.log(tasks.shift());\nconsole.log(tasks);',explanation:'Length-returning and element-returning methods both mutate the list.'},{title:'slice versus splice',code:'const items = ["A", "B", "C", "D"];\nconsole.log(items.slice(1, 3));\nconsole.log(items);\nconsole.log(items.splice(1, 2, "X"));\nconsole.log(items);\nconst result = items.reverse();\nconsole.log(result === items, items);',explanation:'slice copies B and C without mutation. splice removes them and inserts X. reverse mutates and returns the same array.'}],predictions:[predict('v2-method-p1','const a = [1, 2];\nconsole.log(a.push(3), a.length);',['[1, 2, 3] 3','3 3','3 2'],1,'push mutates a and returns its new length.',['3 3']),predict('v2-method-p2','const a = [1, 2, 3];\nconst b = a.slice(0, 2);\nconsole.log(a.length, b.length);',['2 2','3 2','3 3'],1,'slice creates a two-element copy; a stays unchanged.',['3 2'])],debug:exercise('Keep the array after appending an item.','let tasks = ["Read"];\ntasks = tasks.push("Code");\nconsole.log(tasks);','const tasks = ["Read"];\ntasks.push("Code");\nconsole.log(tasks);','Do not assign the length-returning result back to the list.'),activity:exercise('Remove the second task with splice and print removed tasks and remaining tasks.','const tasks = ["Read", "Skip", "Code"];\n// Remove one item at index 1\n','const tasks = ["Read", "Skip", "Code"];\nconst removed = tasks.splice(1, 1);\nconsole.log(removed, tasks);','splice returns the removed elements as an array.'),demo:'For every method, compare the original array, arguments, returned value, updated array, and mutation label in Method Explorer.',transition:'Callbacks let methods transform and summarize the whole collection.'}),
 concept({id:'array-transform',lesson:8,title:'map, filter, reduce, find, some, every & forEach',minutes:20,visual:'transform',what:'A higher-order method accepts a callback function. Different methods use its result to transform, select, combine, or test elements.',why:'Small callback rules make collection-processing logic reusable and readable.',real:'Filter active users, total salaries, find a product, or check whether every mark passes.',analogy:'Send each item through a workstation: map makes one output per item; filter keeps selected items; reduce combines them into one running result.',how:'map returns a new array of callback results. filter returns all values whose callback is truthy; find returns the first match or undefined. some asks whether any element passes; every asks whether all pass. Both can stop early; some([]) is false and every([]) is true. reduce passes accumulator and current value to the callback; start numeric totals with an explicit initial 0, which also handles an empty list. forEach is for side effects and returns undefined. These methods do not inherently mutate the array, but a callback can still mutate an object or the array. They generally skip missing elements of sparse arrays in different ways; use dense arrays in this introduction.',confusion:'map is not for collecting console.log results, which are undefined. filter always returns an array; find returns one value or undefined. reduce must return its next accumulator.',takeaway:'map transforms, filter selects many, find selects one, reduce combines, some/every test, forEach performs effects.',examples:[{title:'Transform, select, combine',code:'const numbers = [1, 2, 3, 4];\nconsole.log(numbers.map(n => n * 2));\nconsole.log(numbers.filter(n => n % 2 === 0));\nconsole.log(numbers.reduce((sum, n) => sum + n, 0));\nconsole.log(numbers);',explanation:'The original list is unchanged because these callbacks do not mutate it.'},{title:'Find and test records',code:'const users = [{ name: "Asha", active: true }, { name: "Dev", active: false }];\nconsole.log(users.filter(user => user.active));\nconsole.log(users.find(user => !user.active)?.name);\nconsole.log(users.some(user => user.active), users.every(user => user.active));\nconst returned = users.forEach(user => console.log(user.name));\nconsole.log(returned);',explanation:'filter returns an array, find returns a record, some/every return booleans, and forEach returns undefined.'}],predictions:[predict('v2-transform-p1','const values = [1, 2, 3];\nconsole.log(values.map(n => n * 2).filter(n => n > 2));',['[2, 4, 6]','[4, 6]','[2, 3]'],1,'map first creates 2,4,6; filter then keeps values greater than 2.',['[4, 6]']),predict('v2-transform-p2','console.log([].reduce((sum, n) => sum + n, 0));\nconsole.log([].some(Boolean), [].every(Boolean));',['0 then false true','0 then false false','TypeError'],0,'The explicit initial accumulator handles an empty list. Any has no match; all has no counterexample.',['0','false true'])],debug:exercise('Return the accumulator from the reducer.','const total = [10, 20].reduce((sum, n) => { sum + n; }, 0);\nconsole.log(total);','const total = [10, 20].reduce((sum, n) => { return sum + n; }, 0);\nconsole.log(total);','A braced callback needs return.'),activity:exercise('Compute salary total and average, safely handling an empty collection.','const salaries = [30000, 45000, 60000];\n// Use reduce with initial 0\n','const salaries = [30000, 45000, 60000];\nconst total = salaries.reduce((sum, salary) => sum + salary, 0);\nconsole.log(total, salaries.length ? total / salaries.length : 0);','Sum first. Divide only when there are elements.'),demo:'Step map, filter, or reduce one element at a time. Compare current input, callback result, output list, and accumulator.',transition:'Ordering a numeric list needs an explicit comparison rule.'}),
 concept({id:'array-sort',lesson:8,title:'Default sorting, numeric comparators & top products',minutes:10,visual:'sort',what:'sort reorders an array in place. Without a comparator, it compares string representations by UTF-16 code-unit order.',why:'Alphabetical-like ordering and numeric ordering answer different questions.',real:'A leaderboard needs highest scores first; a shop can select the top three rated products.',analogy:'Sorting labels on envelopes does not sort the numeric quantities written inside them.',how:'[10,2,30].sort() becomes [10,2,30], because "10" sorts before "2". Use (a,b) => a-b for ascending numbers and b-a for descending. A negative comparator result places a before b, positive after, and zero considers them equal for ordering. JavaScript does not promise one specific internal sorting algorithm, so the simulator compares final results without pretending to reproduce engine internals. Copy with [...values] before sorting to preserve the original. Sort records by a numeric property such as b.rating-a.rating, then slice(0,3).',confusion:'sort does not return an independent array. A comparator returning true/false does not provide the required negative/zero/positive contract.',takeaway:'Numbers need a numeric comparator. Copy before sorting if the original order matters.',examples:[{title:'Compare sort orders',code:'const values = [2, 10, 1, 30];\nconsole.log([...values].sort());\nconsole.log([...values].sort((a, b) => a - b));\nconsole.log(values);',explanation:'The first copy sorts as strings; the second uses numeric order. The original remains untouched.'},{title:'Top three ratings',code:'const products = [{ name: "Pen", rating: 4.2 }, { name: "Book", rating: 4.8 }, { name: "Bag", rating: 4.5 }, { name: "Cup", rating: 4.1 }];\nconst top = [...products].sort((a, b) => b.rating - a.rating).slice(0, 3);\nconsole.log(top.map(product => product.name));',explanation:'The copied container is sorted descending and the first three records are selected.'}],predictions:[predict('v2-sort-p1','console.log([2, 10, 1].sort());',['[1, 2, 10]','[1, 10, 2]','[2, 10, 1]'],1,'Default sorting compares the string forms rather than numeric magnitude.',['[1, 10, 2]']),predict('v2-sort-p2','const values = [3, 1, 2];\nconst result = values.sort((a, b) => a - b);\nconsole.log(result === values, values[0]);',['false 3','true 1','false 1'],1,'sort mutates and returns the original array reference.',['true 1'])],debug:exercise('Replace the boolean comparator with a numeric one.','const values = [10, 2, 30];\nconsole.log(values.sort((a, b) => a > b));','const values = [10, 2, 30];\nconsole.log(values.sort((a, b) => a - b));','Return a negative, zero, or positive number.'),activity:exercise('Select the top three scores without modifying the original list.','const scores = [62, 95, 81, 76, 90];\n// Copy, sort descending, and take three\n','const scores = [62, 95, 81, 76, 90];\nconst top = [...scores].sort((a, b) => b - a).slice(0, 3);\nconsole.log(top, scores);','Spread makes the new array container; slice excludes its end index.'),demo:'Compare default, ascending, and descending sort on the same values. Inspect the original before and after.',transition:'Destructuring extracts values; spread creates a new container, but nested references may remain shared.'}),
 concept({id:'array-copy',lesson:8,title:'Array destructuring, spread & shallow copies',minutes:10,visual:'destructure',what:'Destructuring assigns selected array values to names. Spread expands elements into a new array or argument list.',why:'Named local values and copied containers make data-processing code easier to understand.',real:'A search result can unpack its first item, keep the rest, and combine results from two lists.',analogy:'Unpack a row of bags into named baskets, or place all bags into a new row. The bags themselves may still be the original bags.',how:'const [first,second] = values binds by position. Defaults apply when a selected value is undefined; commas can skip a position. A rest element collects the remaining elements and must be last. [...values] creates a shallow new container; nested objects are still shared. [...a,...b] combines lists. Rest in a pattern collects; spread in an expression expands. Reassigning a destructured primitive does not write back into the original array.',confusion:'A new array reference is not proof that every nested object was cloned.',takeaway:'New container does not necessarily mean new contents.',examples:[{title:'Unpack and combine',code:'const [first, second = "Guest", ...rest] = ["Asha", undefined, "Dev", "Mira"];\nconsole.log(first, second, rest);\nconsole.log([...[1, 2], ...[3, 4]]);',explanation:'The default replaces undefined; rest collects remaining values; spread combines lists.'},{title:'Nested references remain shared',code:'const original = [{ name: "Asha" }];\nconst copy = [...original];\ncopy[0].name = "Mira";\nconsole.log(original === copy, original[0] === copy[0], original[0].name);',explanation:'The containers differ, but they point to the same nested record.'}],predictions:[predict('v2-acopy-p1','const [first, , third] = [10, 20, 30];\nconsole.log(first, third);',['10 20','10 30','20 30'],1,'The empty position skips index 1.',['10 30']),predict('v2-acopy-p2','const original = [{ score: 1 }];\nconst copy = [...original];\ncopy[0].score = 2;\nconsole.log(original[0].score);',['1','2','TypeError'],1,'The shallow copy shares its nested object with the original.',['2'])],debug:exercise('Copy the nested record before mutating it.','const original = [{ score: 1 }];\nconst copy = [...original];\ncopy[0].score = 2;\nconsole.log(original[0].score);','const original = [{ score: 1 }];\nconst copy = original.map(item => ({ ...item }));\ncopy[0].score = 2;\nconsole.log(original[0].score);','Copying each record is enough for this one-level example. Deeper nesting needs more work.'),activity:exercise('Destructure a first product and collect the rest.','const products = ["Pen", "Book", "Bag"];\n// Unpack and print both parts\n','const products = ["Pen", "Book", "Bag"];\nconst [featured, ...others] = products;\nconsole.log(featured, others);','A rest element collects remaining elements into an array.'),demo:'Move named labels onto array indices, then toggle primitive versus object contents in the copy diagram.',transition:'Objects organize the information within each record.'}),
 concept({id:'object-basics',lesson:9,title:'Objects, properties, methods & nested access',minutes:12,visual:'object',what:'An object groups named properties. A method is a function stored as a property and commonly called through that object.',why:'Related facts belong together rather than in unrelated variables.',real:'A student record combines name, marks, address, and useful behavior. An array can hold many such records.',analogy:'A student’s folder has named fields, some containing smaller folders. Arrays are ordered shelves of folders; objects are the labeled facts inside each folder.',how:'An object literal uses {key:value}. Dot notation reads a fixed identifier-like key; bracket notation accepts a string or expression, including keys with spaces. student[field] reads the key held in field; student.field reads the literal key "field". Nested access follows one property at a time. Assign a property to add/update it; delete removes a property. Prefer objects for named fields and arrays for ordered collections. A regular method’s this still depends on its call site, as explained in chapter 7.',confusion:'A dynamic key requires brackets. Object properties may use keyword-like names even though binding names have separate reserved-word rules.',takeaway:'Use dots for fixed known keys, brackets for keys computed at runtime.',examples:[{title:'Build a student folder',code:'const student = { name: "Asha", marks: 82, address: { city: "Pune" }, label() { return this.name + ": " + this.marks; } };\nconsole.log(student.name, student.address.city);\nconsole.log(student.label());\nstudent.marks = 90;\nconsole.log(student.marks);',explanation:'The object stores data and a regular method. Calling student.label() supplies student as its receiver.'},{title:'Dynamic keys and deletion',code:'const product = { name: "Pen", "unit price": 20 };\nconst field = "name";\nconsole.log(product[field], product["unit price"]);\nproduct.stock = 5;\ndelete product.stock;\nconsole.log(product.stock);',explanation:'Brackets handle an expression or a key containing a space. A missing property reads undefined.'}],predictions:[predict('v2-object-p1','const user = { name: "Asha", field: "Other" };\nconst field = "name";\nconsole.log(user[field], user.field);',['Asha Other','name Other','Asha Asha'],0,'The bracket expression evaluates field to name; dot notation uses the literal key field.',['Asha Other']),predict('v2-object-p2','const user = { score: 5 };\ndelete user.score;\nconsole.log(user.score);',['5','null','undefined'],2,'The removed property is missing, so its value lookup returns undefined.',['undefined'])],debug:exercise('Read the property selected by the variable.','const student = { name: "Asha" };\nconst key = "name";\nconsole.log(student.key);','const student = { name: "Asha" };\nconst key = "name";\nconsole.log(student[key]);','Brackets evaluate key; dots do not.'),activity:exercise('Create a nested profile and read the city with both fixed and dynamic access.','// Profile needs name and address.city\n','const profile = { name: "Asha", address: { city: "Pune" } };\nconst field = "city";\nconsole.log(profile.address.city, profile.address[field]);','Each property read selects the next object in the path.'),demo:'Expand nested folders in Object Inspector. Add, update, delete, and inspect a property in the property editor.',transition:'Destructuring gives frequently used fields local names.'}),
 concept({id:'object-iteration',lesson:9,title:'Object destructuring, keys, values & entries',minutes:12,visual:'object-iteration',what:'Object destructuring extracts fields by key. Object.keys, values, and entries turn selected own properties into arrays for processing.',why:'Records often need reporting, validation, or conversion into a list of display rows.',real:'A profile inspector displays key/value pairs, while a stock report sums inventory quantities.',analogy:'Read a folder’s field names, just its contents, or labeled pairs. Destructuring copies selected field values onto named cards.',how:'const {name, marks:score, city="Unknown"} = student extracts name, renames marks to score, and defaults city when its value is undefined. Nested patterns can extract nested fields but throw when a required intermediate object is missing. Object.keys/values/entries include own enumerable string-keyed properties, not symbol keys. for…in additionally visits inherited enumerable string keys; filter with Object.hasOwn when only own fields are wanted. An entry pair is an array, so for (const [key,value] of Object.entries(record)) combines object iteration and array destructuring.',confusion:'A renamed destructuring pattern {marks:score} declares score, not a second local marks binding.',takeaway:'Keys name fields, values hold data, entries pair them.',examples:[{title:'Destructure and rename',code:'const student = { name: "Asha", marks: 82, address: { city: "Pune" } };\nconst { name, marks: score, age = 18, address: { city } } = student;\nconsole.log(name, score, age, city);',explanation:'Renaming creates score, defaults fill undefined, and a nested pattern reads city.'},{title:'Own versus inherited fields',code:'const record = Object.create({ inherited: 1 });\nrecord.own = 2;\nfor (const key in record) console.log(key, Object.hasOwn(record, key));\nconsole.log(Object.keys(record), Object.values(record));\nfor (const [key, value] of Object.entries(record)) console.log(key, value);',explanation:'for…in sees the inherited enumerable property too. The Object helpers select own enumerable string keys.'}],predictions:[predict('v2-oiterate-p1','const student = { marks: 82 };\nconst { marks: score } = student;\nconsole.log(score);',['undefined','82','ReferenceError'],1,'The property marks is assigned to the local binding score.',['82']),predict('v2-oiterate-p2','const record = Object.create({ inherited: 1 });\nrecord.own = 2;\nconsole.log(Object.keys(record).length);',['1','2','0'],0,'Object.keys excludes the inherited property.',['1'])],debug:exercise('Use the new local name after renaming a property.','const student = { marks: 82 };\nconst { marks: score } = student;\nconsole.log(marks);','const student = { marks: 82 };\nconst { marks: score } = student;\nconsole.log(score);','The local variable is score.'),activity:exercise('Print every own stock field as a key/value pair.','const stock = { pens: 12, books: 5 };\n// Iterate entries\n','const stock = { pens: 12, books: 5 };\nfor (const [name, quantity] of Object.entries(stock)) console.log(name, quantity);','Object.entries gives iterable pairs.'),demo:'Switch the inspector between keys, values, entries, and for…in, including an inherited example.',transition:'When you hand a record to another part of an app, decide whether it should share or copy it.'}),
 concept({id:'object-copy',lesson:9,title:'Reference equality, spread, Object.assign & structuredClone',minutes:16,advanced:true,visual:'copy',what:'Assignment shares an object reference. A shallow copy creates a new outer object but keeps nested references. A supported deep clone can create independent nested data.',why:'An edit preview should not accidentally modify the saved record through shared nested properties.',real:'A profile editor can clone an address before changing its city, while an inventory app may intentionally share one live product record.',analogy:'A second address card points to the same house. A copied floor plan is new paper, but a shallow copy may still refer to the original rooms.',how:'const b = a shares identity. {...a} and Object.assign({},a) copy own enumerable properties shallowly; Object.assign(target,source) mutates its target. Comparing objects with === checks identity, not equal contents. structuredClone makes a deep copy of supported data, including cycles, dates, maps, and sets, but cannot clone functions, symbol values, or DOM nodes; it also does not preserve every custom prototype or property descriptor. It is available in modern browsers/workers, but feature-check where older environments matter. JSON stringify/parse is not a general substitute because it loses or rejects several types.',confusion:'copy !== original only proves the outer object differs. copy.address may still be original.address.',takeaway:'Trace every nested arrow before claiming an independent copy.',examples:[{title:'Three different relationships',code:'const original = { name: "Asha", address: { city: "Pune" } };\nconst alias = original;\nconst shallow = { ...original };\nconst assigned = Object.assign({}, original);\nconst deep = structuredClone(original);\nshallow.address.city = "Delhi";\nconsole.log(alias === original, shallow === original);\nconsole.log(original.address.city, assigned.address.city, deep.address.city);',explanation:'The shallow copies still share address. The deep clone keeps its independent Pune address.'},{title:'Clone limits',code:'try {\n structuredClone({ action() { return 1; } });\n} catch (error) { console.log(error.name); }\nconst original = { count: 1 };\nconsole.log(original === { count: 1 });',explanation:'A function value cannot be structured-cloned. Equal-looking object literals still have different identities.'}],predictions:[predict('v2-copy-p1','const a = { nested: { value: 1 } };\nconst b = { ...a };\nb.nested.value = 2;\nconsole.log(a.nested.value, a === b);',['1 false','2 false','2 true'],1,'Only the outer container was copied, so the nested mutation is shared.',['2 false']),predict('v2-copy-p2','const a = { nested: { value: 1 } };\nconst b = structuredClone(a);\nb.nested.value = 2;\nconsole.log(a.nested.value, b.nested.value);',['2 2','1 2','1 1'],1,'The supported nested data is independently cloned.',['1 2'])],debug:exercise('Make this nested edit independent.','const saved = { address: { city: "Pune" } };\nconst draft = { ...saved };\ndraft.address.city = "Delhi";\nconsole.log(saved.address.city);','const saved = { address: { city: "Pune" } };\nconst draft = structuredClone(saved);\ndraft.address.city = "Delhi";\nconsole.log(saved.address.city);','For this supported plain data, deep cloning separates the nested address.'),activity:exercise('Make a targeted shallow copy of the nested address without changing the saved record.','const saved = { name: "Asha", address: { city: "Pune" } };\n// Copy both affected levels\n','const saved = { name: "Asha", address: { city: "Pune" } };\nconst draft = { ...saved, address: { ...saved.address, city: "Delhi" } };\nconsole.log(saved.address.city, draft.address.city);','Copy the outer record and the address you are changing.'),demo:'Choose direct assignment, spread, Object.assign, or deep clone. Mutate top-level and nested fields and follow the reference arrows.',transition:'Missing fields and dynamically selected keys need deliberate access rules.'}),
 concept({id:'optional-computed',lesson:9,title:'Optional chaining, computed keys & safe data access',minutes:12,visual:'properties',what:'Optional chaining stops a property access when its left operand is null or undefined. A computed property name evaluates an expression to choose a key.',why:'Real API records may omit nested data, and form fields may select property names dynamically.',real:'A profile can show a fallback city when no address is provided; a settings editor can update a chosen field.',analogy:'Check whether the next folder exists before opening it. A computed label uses the current name printed on a selected tab.',how:'student.address?.city protects a missing address when student exists. student?.address?.city also protects a nullish student binding; it cannot protect a completely undeclared identifier. The result is undefined when short-circuited; ?? can select a fallback for null/undefined without replacing valid empty strings or zero. Optional chaining is for access, not an assignment target. { [field]: value } computes a property name at creation. record[field] then accesses it dynamically. Validate allowed keys in real editors rather than blindly accepting arbitrary external keys.',confusion:'student.address?.city does not protect an undeclared student, and ?. does not swallow unrelated errors or protect a misspelled binding.',takeaway:'Guard the missing level; compute the key deliberately.',examples:[{title:'Handle a missing address',code:'const student = { name: "Asha" };\nconsole.log(student.address?.city);\nconsole.log(student.address?.city ?? "City not provided");\nconst absent = null;\nconsole.log(absent?.address?.city);',explanation:'The optional chain yields undefined when an intermediate value is nullish.'},{title:'Compute a property name',code:'const field = "nickname";\nconst profile = { name: "Asha", [field]: "Ash" };\nconsole.log(profile[field]);\nconst { name, nickname = "No nickname" } = profile;\nconsole.log(name, nickname);',explanation:'The expression field becomes the key nickname; destructuring then extracts its value.'}],predictions:[predict('v2-optional-p1','const student = {};\nconsole.log(student.address?.city ?? "Unknown");',['TypeError','Unknown','null'],1,'The missing address short-circuits the access, and ?? selects the fallback.',['Unknown']),predict('v2-optional-p2','const field = "score";\nconst record = { [field]: 0 };\nconsole.log(record.score ?? 100);',['0','100','undefined'],0,'The computed key is score. Nullish fallback preserves zero.',['0'])],debug:exercise('Guard the missing address before reading city.','const user = { name: "Asha" };\nconsole.log(user.address.city);','const user = { name: "Asha" };\nconsole.log(user.address?.city ?? "Unknown");','Place ?. before the property read through the missing address.'),activity:exercise('Build a profile with a computed field and display a safe city fallback.','const field = "role";\n// Create the record and safely read its city\n','const field = "role";\nconst profile = { name: "Asha", [field]: "Learner" };\nconsole.log(profile[field], profile.address?.city ?? "Unknown");','Use [field] in the literal and ?. for the optional address.'),demo:'Add or remove the address in Object Inspector, choose a computed key, and observe the fallback without a page error.',transition:'Combine records, collections, and functions in the student manager and inventory projects.'})
];
advancedConcepts.push(concept({id:'closures',lesson:7,title:'Optional deeper dive: closures & binding lifetime',minutes:12,advanced:true,visual:'closure',what:'A closure is a function together with access to bindings in its surrounding lexical environment, even after the outer function has returned.',why:'A helper can remember private state between calls without using one shared global variable.',real:'Independent counters, form helpers, and event callbacks can keep access to state created during setup.',analogy:'Each visit to a workshop creates a notebook. A returned assistant keeps the key to that visit’s notebook after the workshop visit ends.',how:'Calling makeCounter creates a new count binding and returns an arrow that reads and updates that binding. Later calls to the returned arrow use the same binding, not a frozen copy of its old value. Calling makeCounter a second time creates a different environment with its own count. This explains why visibility and lifetime differ: count is not directly visible outside makeCounter, but a reachable returned function still uses it. Once neither a function nor another reachable value needs that environment, it can be garbage-collected; exact collection timing is not guaranteed.',confusion:'A closure does not copy the variable’s value at function creation. It retains access to the binding. Two functions created by separate outer calls need not share that binding.',takeaway:'A returned function can remember its own outer call’s state.',examples:[{title:'One counter remembers',code:'function makeCounter() {\n let count = 0;\n return () => ++count;\n}\nconst next = makeCounter();\nconsole.log(next(), next(), next());',explanation:'The outer call has finished, but next still reaches and updates the same count binding.'},{title:'Separate calls, separate notebooks',code:'function makeCounter() {\n let count = 0;\n return () => ++count;\n}\nconst first = makeCounter();\nconst second = makeCounter();\nconsole.log(first(), first(), second(), first());',explanation:'first and second come from separate outer calls, so their counters are independent.'}],predictions:[predict('v2-closure-p1','function makeCounter() { let n = 0; return () => ++n; }\nconst a = makeCounter(), b = makeCounter();\nconsole.log(a(), a(), b());',['1 2 1','1 2 3','1 1 1'],0,'Two calls to the factory create two different n bindings.',['1 2 1']),predict('v2-closure-p2','function makeReader() {\n let value = 1;\n const read = () => value;\n value = 2;\n return read;\n}\nconsole.log(makeReader()());',['1','2','ReferenceError'],1,'The closure reads the binding’s current value, not a snapshot of 1.',['2'])],debug:exercise('Create independent closure state instead of one shared outer counter.','let count = 0;\nfunction makeCounter() { return () => ++count; }\nconst a = makeCounter(), b = makeCounter();\nconsole.log(a(), b());','function makeCounter() {\n let count = 0;\n return () => ++count;\n}\nconst a = makeCounter(), b = makeCounter();\nconsole.log(a(), b());','Declare count inside each factory call.'),activity:exercise('Return a helper that remembers a chosen greeting prefix.','function makeGreeting(prefix) {\n // Return a function accepting a name\n}\nconst welcome = makeGreeting("Welcome");\nconsole.log(welcome("Asha"));','function makeGreeting(prefix) {\n return name => prefix + ", " + name;\n}\nconst welcome = makeGreeting("Welcome");\nconsole.log(welcome("Asha"));','The returned function can read prefix from its defining environment.'),demo:'Call the first and second counters independently, then create fresh counters and watch each private notebook restart.',transition:'Closures and callbacks explain how array transformations keep access to the rules surrounding them.'}));
